  const base=new THREE.Mesh(new THREE.SphereGeometry(.075,24,10,0,Math.PI*2,0,Math.PI/2),lampBlack); base.scale.y=.7; base.position.set(lx,y,lz); base.userData=pick; scene.add(base);
