  const hit=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,.48,10),new THREE.MeshBasicMaterial({visible:false})); hit.position.set(lx,y+.24,lz); hit.userData=pick; scene.add(hit); pickables.push(hit);
