  const cen=lathe([[0,0],[.035,0],[.05,.03],[.048,.055],[.04,.06]],new THREE.MeshStandardMaterial({color:0x6a5a3a,metalness:.6,roughness:.4}),18); cen.position.set(bx+.52,top,z0+.26); scene.add(cen);
